"""Reader section for the fixed-montage five-material forward experiment."""


def result_sections(md,code):
    md(r'''## 5.5. Добавление жира при неизменном положении сборок

Предыдущая проверка показала, что кости важны для восстановления сопротивления лёгкого, но их выделение вместе с сердцем не устраняет расхождение базового импеданса с экспериментом. Следующий проверяемый фактор — жировая ткань. Здесь выполняется только **прямая задача**: свойства тканей задаются по литературе, а импеданс рассчитывается для всех девяти размеров. Положение сборок и сопротивления по измерениям не подбираются.

Сохранённые маски TotalSegmentator v2 действительно содержали подкожный жир и внутренний жир туловища. Однако они были получены на укороченной сердечной серии КТ: область по продольной координате от −237,44 до −78,07 мм не покрывала верхний край самой длинной сборки. Отсутствующую область нельзя считать областью без жира. Поэтому для этого опыта **TotalSegmentator 2.18.0 повторно запущен на полной статической серии той же КТ**, из которой происходит исходная анатомия FEM. Преобразование DICOM проверяло порядок и шаг срезов; использованы 241 срез с шагом 0,765625 × 0,765625 × 1,25 мм. Смена системы координат RAS → LPS выполняет только стандартное обращение двух осей, без подбора смещения или поворота по импедансам.

Задача `total` выделяет доли лёгких, кости и всё сердце; `tissue_types` — подкожный и внутренний жир. Классы каждого органа объединяются в объёмную маску. Жир представлен объединением двух жировых классов, а остальной объём принят мягкими тканями со свойствами мышцы. Эти определения соответствуют [задачам TotalSegmentator](https://github.com/wasserth/TotalSegmentator#subtasks); автоматическая сегментация остаётся исследовательским входом с неустановленной анатомической погрешностью.

**Сетка и электроды сохранены.** Используются прежняя наружная поверхность тела, узлы и элементы, положение C01 и четыре конечных контакта диаметром 5 мм для каждого измерения. Все центры электродов лежат в поле полной КТ. Центры элементов суммарным объёмом около 952 мл (4,72% расчётного тела) лежат вне поля КТ, в том числе в продолжениях рук; вне поля сохраняется мягкотканный фон. Указанный объём оценён по центрам элементов, а не по точному пересечению границы поля с каждым тетраэдром. Это явное допущение на границе доступной анатомии, а не результат сегментации.

Новые маски органов не совпадают со старыми. Поэтому рассчитаны две согласованные версии: **новые кости, лёгкие и сердце, но жир со свойствами фона**; **те же маски с отдельными свойствами жира**. Прежняя четырёхтканная модель сохранена третьей кривой для сравнения. Разность первых двух версий выделяет влияние электрических свойств жира. Отличие новой версии без жира от прежней включает изменения границ органов и способа их переноса на сетку; оно не является измеренной ошибкой старой сегментации.

Чтобы тонкие участки жира не исчезали при назначении материала только по центру элемента, внутри каждого тетраэдра оцениваются объёмные доли пяти тканей. Для линейных конечных элементов градиенты базисных функций постоянны, поэтому локальная матрица проводимости определяется интегралом проводимости по объёму. Используется средняя проводимость, взвешенная по долям; среднее удельное сопротивление не подставляется вместо неё. Первое сравнение 256 и 1024 точек не выполнило заданный численный порог: максимальное изменение импеданса составило 0,230 Ом. Поэтому интегрирование уточнено до 4096 точек. Основной результат соответствует 4096 точкам и сравнивается с 1024 точками; наборы вложены друг в друга. Это проверка интегрирования на прежней сетке; она не доказывает, что сетка разрешает все тонкие слои и межтканевые границы.

При пересечении независимых масок действует фиксированный приоритет: лёгкое → кость → сердце → жир → остаточный фон. Размеры пересечений в вокселях сохранены в протоколе. Кость целиком получает свойства кортикальной кости, сердце — сердечной мышцы, без отдельных кровяных полостей. Подкожному и внутреннему жиру назначены одинаковые свойства категории Fat из [IT’IS V5.0](https://itis.swiss/virtual-population/tissue-properties/downloads/database-v5-0). Это дополнительное допущение о свойствах двух жировых классов. Частоты 50 и 100 кГц обозначают два литературных сценария; действительные проводимости и постоянное контактное сопротивление используются так же, как в разделе 5.4.

**Таблица 4е. Объёмы материалов внутри неизменённой FEM-модели и литературные сопротивления.** Объёмы относятся к новой разметке с 4096 точками интегрирования в элементе. Для лёгкого отдельно указаны свойства inflated и deflated; в обоих случаях его геометрия остаётся геометрией КТ на вдохе.''')
    code('''from lateral_fat_analysis import OUT as FAT_OUT, figure as fat_figure
fat_qc=json.loads((FAT_OUT/'qc.json').read_text(encoding='utf-8'))
assert fat_qc['complete'] and fat_qc['quadrature_all_within_tolerance']
for n,h in {**fat_qc['inputs_sha256'],**fat_qc['outputs_sha256']}.items():
    assert sha(FAT_OUT/n)==h,n
fat_inc=pd.read_csv(FAT_OUT/'increments.csv')
fat_metrics=pd.read_csv(FAT_OUT/'metrics.csv')
fat_lit=pd.read_csv(FAT_OUT/'literature_values.csv')
fat_volume=pd.read_csv(FAT_OUT/'material_inventory.csv').query('quadrature_points==4096').set_index('tissue').volume_ml
fat_rows=[]
for key,label,tissue in [('soft_background','Остальные мягкие ткани','Muscle'),('lung','Лёгкое: inflated','Lung (Inflated)'),('lung','Лёгкое: deflated','Lung (Deflated)'),('bone','Кость','Bone (Cortical)'),('heart','Сердце','Heart Muscle'),('fat','Жир','Fat')]:
    values=fat_lit[fat_lit.tissue==tissue].set_index('frequency_hz').rho_ohm_m
    fat_rows.append([label,num(fat_volume[key],1),num(values[50000],3),num(values[100000],3)])
table(pd.DataFrame(fat_rows,columns=['Материал','Объём, мл','ρ при 50 кГц, Ом·м','ρ при 100 кГц, Ом·м']))
''')
    md(r'''**Рисунок 7. Влияние жира и перехода к новой разметке при прежнем положении сборок.** Верхние панели показывают базовые импедансы: слева — вдох, справа — условное сопоставление deflated с выдохом. Красная кривая — эксперимент, серая — прежние маски без отдельного жира, синяя — новые маски с заменой жира фоном, оранжевая — новая пятикомпонентная модель. Нижние панели разделяют эффект свойств жира и эффект перехода к новой разметке. Положительная разность означает увеличение импеданса. Частота переключается в списке; экспериментальные точки остаются одинаковыми.

Сближение оранжевой и красной кривых означает уменьшение расхождения в прямой задаче. Оно не подтверждает истинность заданных сопротивлений и не показывает точность их обратного восстановления. Отрезки соединяют рассчитанные размеры, а интервалы неопределённости не приведены, поскольку совокупная погрешность эксперимента не установлена. Геометрия вдоха фиксирована; категория deflated не установлена как реальный выдох добровольца.''')
    code('show(fat_figure())')
    code('''for freq in [50000,100000]:
    a=fat_inc[fat_inc.frequency_hz==freq]
    paragraph(f"**При {freq//1000} кГц** выделение жира меняет импеданс на **{num(a.fat_delta_ohm.min(),3)}…{num(a.fat_delta_ohm.max(),3)} Ом**, или {num(a.fat_delta_pct.min(),2)}…{num(a.fat_delta_pct.max(),2)}% относительно новой модели с заменой жира фоном. Диапазон охватывает девять размеров и два табличных состояния лёгкого.")
''')
    md('''**Таблица 4ж. Прогноз пятикомпонентной модели при 50 кГц для каждой сборки, Ом.** Сопротивления заданы до сравнения с наблюдениями. Вторая пара столбцов использует условный сценарий deflated; это ограничение сохраняется при оценке совпадения.''')
    code('''a=fat_inc[fat_inc.frequency_hz==50000]
fat_table=[]
for length in sorted(a.L_mm.unique()):
    g=a[a.L_mm==length].set_index('state')
    fat_table.append([length,g.loc['inhale','Z_experiment'],g.loc['inhale','ts_with_fat'],g.loc['exhale','Z_experiment'],g.loc['exhale','ts_with_fat']])
table(pd.DataFrame(fat_table,columns=['L, мм','Вдох: эксперимент','Вдох: расчёт','Выдох: эксперимент','Условный выдох: расчёт']))
''')
    md('''**Таблица 4з. Среднеквадратичное расхождение с девятью измерениями, Ом.** Меньшее значение означает более близкий прямой прогноз при выбранных литературных параметрах. Оно не является ошибкой относительно независимо установленного истинного сопротивления ткани.''')
    code('''a=fat_metrics.pivot(index=['frequency_hz','state'],columns='model',values='rmse_ohm').reset_index()
a.columns.name=None
a['frequency_hz']=a.frequency_hz/1000;a['state']=a.state.map({'inhale':'Вдох','exhale':'Условный выдох'})
table(a[['frequency_hz','state','previous_four_tissue','ts_without_fat','ts_with_fat']].rename(columns={'frequency_hz':'Частота, кГц','state':'Состояние','previous_four_tissue':'Прежняя модель','ts_without_fat':'Новые маски, жир = фон','ts_with_fat':'Новые маски + жир'}))
paragraph(f"Численный контроль: выполнено **{fat_qc['new_CEM_solutions']} прямых FEM/CEM-решений уточнённого опыта**, включая сравнение двух уровней интегрирования и предельные случаи равенства свойств. Максимальное изменение Z между 1024 и 4096 точками составляет **{num(fat_qc['quadrature_max_difference_ohm'],4)} Ом** ({num(fat_qc['quadrature_max_difference_pct'],4)}%). Предыдущий расчёт включал ещё 189 решений и сохранён отдельно. Все состояния уточнённого опыта удовлетворяют заранее заданному численному условию |ΔZ| ≤ 0,02 Ом + 0,001|Z|. Это условие не задаёт шум прибора или допустимую ошибку ρ₂. Максимальная относительная невязка системы — {fat_qc['max_relative_residual']:.2e}, ошибка взаимности — {fat_qc['max_reciprocity_ohm']:.2e} Ом.")
''')
    code("""a=fat_metrics[fat_metrics.frequency_hz==50000].set_index(['state','model'])
paragraph(f"**Согласие с экспериментом улучшилось, но остаётся неполным.** При 50 кГц среднеквадратичное расхождение на вдохе уменьшилось с {num(a.loc[('inhale','ts_without_fat'),'rmse_ohm'],2)} до {num(a.loc[('inhale','ts_with_fat'),'rmse_ohm'],2)} Ом; в условном сценарии выдоха — с {num(a.loc[('exhale','ts_without_fat'),'rmse_ohm'],2)} до {num(a.loc[('exhale','ts_with_fat'),'rmse_ohm'],2)} Ом. Прогноз с жиром остаётся ниже измерений для всех девяти размеров в обоих состояниях. Среднее абсолютное относительное расхождение составляет соответственно {num(a.loc[('inhale','ts_with_fat'),'mape_pct'],1)} и {num(a.loc[('exhale','ts_with_fat'),'mape_pct'],1)}%.")
""")
    md(r'''**Вывод.** Для данного монтажа отдельное описание жира существенно меняет базовый импеданс. Жир расположен близко к контактам, и его сопротивление в выбранном литературном сценарии выше сопротивления мышечного фона. Поэтому результат не следует оценивать только по доле жира в общем объёме тела: имеет значение его расположение относительно распределения тока и измерительной чувствительности. Пятикомпонентная модель позволяет проверить, какая часть прежнего расхождения связана с заменой жира мышечной тканью. Оставшееся расхождение требует дальнейшего разбора условий модели и эксперимента.

Этот опыт не восстанавливает новые ρ₁ и ρ₂ и не определяет, можно ли заменить жир одним эффективным параметром без потери точности обратной задачи. Для такого вывода потребуется отдельная проверка восстановления, подобная выполненной для костей в разделе 5.4. Новая локализация здесь не запускалась. Следующее сравнение положений должно подбирать общую пару сопротивлений по всем сборкам, как сформулировано выше, с явным определением состава оставшегося мягкотканного фона.

[Все численные результаты, происхождение масок и команды повторения](../MATLAB_TRKG4_real_subjects/output/exploratory/lateral_fat_20260916/README.md) сохранены отдельно. Диагностический срез масок проходит именно по плоскости текущей сборки; он служит контролю переноса и не заменяет посрезовую анатомическую валидацию.''')
